@staticmethod
def to_python(field, object_id):
    """
    Convert an object_id extracted from the URL to a Python value using
    the field's to_python(). For a composite primary key, object_id is a
    tuple/list of quoted parts (or a single quoted value) which is split
    into its parts first.
    """
    if isinstance(field, models.CompositePrimaryKey):
        if isinstance(object_id, str):
            parts = split_parts(object_id)
        else:
            parts = list(object_id)
        if len(parts) != len(field.fields):
            raise ValidationError(
                "The composite primary key must have %d parts." % len(field.fields)
            )
        object_id = [
            component_field.to_python(unquote(part))
            for component_field, part in zip(field.fields, parts)
        ]
    return field.to_python(object_id)

